//! Independent ABI-2 examples: bytes and results are written from the specification,
//! never generated by the assembler or the instruction encoder under test.

use cos_tools::isa::{self, Instruction, Opcode};
use cos_tools::vm::{Bounds, FaultCause, Memory, Outcome, Range, ReturnValues, Vm};

const BASE: u32 = 0x04_0000;
const STACK_FIRST: u32 = 0x05_ff80;
const STACK_LAST: u32 = 0x05_ffff;

fn fixture(words: &[[u8; 4]]) -> (Vm, Memory) {
    fixture_at(words, BASE, STACK_LAST)
}

fn fixture_at(words: &[[u8; 4]], base: u32, arena_last: u32) -> (Vm, Memory) {
    let bounds = Bounds {
        arena: Range {
            first: base,
            last: arena_last,
        },
        code: Range {
            first: base,
            last: base + words.len() as u32 * 4 - 1,
        },
        heap: Range {
            first: base + 0x100,
            last: arena_last - 0x80,
        },
        stack: Range {
            first: arena_last - 0x7f,
            last: arena_last,
        },
    };
    let vm = Vm::new(0x1234, bounds, base, None).unwrap();
    let mut memory = Memory::new();
    let bytes: Vec<u8> = words.iter().flatten().copied().collect();
    memory.write(base, &bytes).unwrap();
    (vm, memory)
}

fn one(word: [u8; 4]) -> (Vm, Memory) {
    fixture(&[word, [0x20, 0x00, 0x00, 0x04]])
}

fn step(vm: &mut Vm, memory: &mut Memory) {
    vm.refuel(1);
    assert!(matches!(vm.run(memory), Outcome::FuelExhausted));
}

fn fault(vm: &mut Vm, memory: &mut Memory, expected: FaultCause) {
    let pc = vm.state.pc;
    match vm.run(memory) {
        Outcome::Fault(fault) => {
            assert_eq!(fault.pid, 0x1234);
            assert_eq!(fault.pc, pc);
            assert_eq!(fault.cause, expected);
        }
        other => panic!("expected {expected:?}, received {other:?}"),
    }
}

#[test]
fn valid_encodings_cover_every_defined_opcode() {
    let examples = [
        [0x00, 0, 0, 0],
        [0x01, 0x73, 0, 0],
        [0x02, 7, 0x34, 0x12],
        [0x03, 0x73, 0, 0],
        [0x04, 0x73, 0, 0],
        [0x05, 0x73, 0, 0],
        [0x06, 0x73, 0, 0],
        [0x07, 0x73, 0, 0],
        [0x08, 7, 15, 0],
        [0x09, 7, 15, 0],
        [0x0a, 7, 15, 0],
        [0x0b, 7, 0x34, 0x12],
        [0x0c, 7, 0, 0],
        [0x0d, 7, 0, 0],
        [0x0e, 7, 0, 0],
        [0x10, 0x37, 0x34, 0x12],
        [0x11, 0x37, 0x34, 0x12],
        [0x12, 0x37, 0x34, 0x12],
        [0x13, 0x37, 0x34, 0x12],
        [0x14, 0x13, 0x56, 0x34],
        [0x15, 0x13, 0x56, 0x34],
        [0x16, 0x13, 0, 0],
        [0x17, 0x62, 0, 0],
        [0x18, 0x62, 0, 0],
        [0x19, 0x37, 0, 0],
        [0x1a, 0x37, 0, 0],
        [0x1b, 2, 6, 7],
        [0x1c, 0x12, 0x34, 0x56],
        [0x1d, 0x12, 0x34, 0x56],
        [0x1e, 0x12, 0x34, 0x56],
        [0x1f, 0x12, 0x34, 0x56],
        [0x20, 0x12, 0x34, 0x56],
        [0x21, 0x12, 0x34, 0x56],
        [0x22, 0, 0, 0],
        [0x23, 0x76, 0xfe, 0xff],
        [0x24, 0x76, 0xfe, 0xff],
        [0x25, 0x76, 0xfe, 0xff],
        [0x26, 0x76, 0xfe, 0xff],
        [0x27, 0x76, 0xfe, 0xff],
        [0x28, 0x76, 0xfe, 0xff],
        [0x29, 0x13, 0xfe, 0xff],
        [0x2a, 0x13, 0xfe, 0xff],
        [0x2b, 0x13, 0xfe, 0xff],
        [0x2c, 0x13, 0xfe, 0xff],
        [0x30, 7, 0, 0],
        [0x31, 7, 0, 0],
        [0x32, 3, 0, 0],
        [0x33, 3, 0, 0],
        [0x34, 3, 0, 0],
        [0x35, 3, 0, 0],
        [0x36, 0xff, 0, 0],
        [0x37, 0, 0, 0],
        [0x38, 0, 7, 0x10],
        [0x39, 0, 0, 0],
        [0x3a, 0, 0, 0],
    ];
    for bytes in examples {
        assert!(isa::decode(bytes).is_ok(), "valid encoding {bytes:02x?}");
    }
    for opcode in 0..=255_u8 {
        let defined = examples.iter().any(|bytes| bytes[0] == opcode);
        if !defined {
            assert!(
                isa::decode([opcode, 0, 0, 0]).is_err(),
                "reserved opcode {opcode:02x}"
            );
        }
    }
}

#[test]
fn encoding_and_decoding_match_independent_known_bytes() {
    let cases = [
        (Opcode::Nop, 0, 0, 0, [0x00, 0, 0, 0]),
        (Opcode::Mov, 3, 7, 0, [0x01, 0x73, 0, 0]),
        (Opcode::Ldi, 5, 0, 0x1234, [0x02, 5, 0x34, 0x12]),
        (Opcode::Sar, 7, 0, 15, [0x0a, 7, 15, 0]),
        (Opcode::St16, 7, 3, 0xabcd, [0x13, 0x37, 0xcd, 0xab]),
        (Opcode::Stp, 3, 1, 0x3456, [0x15, 0x13, 0x56, 0x34]),
        (Opcode::Pmov, 3, 1, 0, [0x16, 0x13, 0, 0]),
        (Opcode::Padd, 2, 6, 0, [0x17, 0x62, 0, 0]),
        (Opcode::Pgethi, 7, 3, 0, [0x1a, 0x37, 0, 0]),
        (Opcode::Pmake, 2, 6, 7, [0x1b, 2, 6, 7]),
        (Opcode::Pli2, 2, 0, 0x563412, [0x1e, 0x12, 0x34, 0x56]),
        (Opcode::Call, 0, 0, 0x04010c, [0x21, 0x0c, 1, 4]),
        (Opcode::Blts, 6, 7, 0xfffe, [0x27, 0x76, 0xfe, 0xff]),
        (Opcode::Pbgeu, 3, 1, 0x8000, [0x2c, 0x13, 0, 0x80]),
        (Opcode::Push16, 7, 0, 0, [0x30, 7, 0, 0]),
        (Opcode::Popp, 3, 0, 0, [0x33, 3, 0, 0]),
        (Opcode::Syscall, 0xff, 0, 0, [0x36, 0xff, 0, 0]),
        (Opcode::Trap, 0, 0, 0x1007, [0x38, 0, 7, 0x10]),
        (Opcode::Mulu, 0, 0, 0, [0x39, 0, 0, 0]),
        (Opcode::Muls, 0, 0, 0, [0x3a, 0, 0, 0]),
    ];
    for (op, a, b, immediate, bytes) in cases {
        let expected = Instruction {
            op,
            a,
            b,
            immediate,
        };
        assert_eq!(isa::decode(bytes).unwrap(), expected);
        assert_eq!(isa::encode(expected).unwrap(), bytes);
    }
    for instruction in [
        Instruction {
            op: Opcode::Ldi,
            a: 0,
            b: 0,
            immediate: 0x1_0000,
        },
        Instruction {
            op: Opcode::Pli0,
            a: 0,
            b: 0,
            immediate: 0x100_0000,
        },
        Instruction {
            op: Opcode::Pli2,
            a: 1,
            b: 0,
            immediate: 0,
        },
        Instruction {
            op: Opcode::Shl,
            a: 0,
            b: 0,
            immediate: 16,
        },
        Instruction {
            op: Opcode::Pmake,
            a: 0,
            b: 0,
            immediate: 8,
        },
        Instruction {
            op: Opcode::Mov,
            a: 16,
            b: 0,
            immediate: 0,
        },
        Instruction {
            op: Opcode::Nop,
            a: 0,
            b: 0,
            immediate: 0x1_0000,
        },
    ] {
        assert!(
            isa::encode(instruction).is_err(),
            "encoder silently truncated {instruction:?}"
        );
    }
}

#[test]
fn invalid_registers_shift_counts_and_reserved_fields_are_rejected() {
    let mut bad = Vec::new();
    for op in [0x00, 0x22, 0x37, 0x39, 0x3a] {
        bad.extend([[op, 1, 0, 0], [op, 0, 1, 0], [op, 0, 0, 1]]);
    }
    for op in [
        0x01, 0x03, 0x04, 0x05, 0x06, 0x07, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28,
    ] {
        bad.extend([[op, 0x08, 0, 0], [op, 0x80, 0, 0], [op, 0xff, 0, 0]]);
    }
    for op in [0x01, 0x03, 0x04, 0x05, 0x06, 0x07] {
        bad.extend([[op, 0, 1, 0], [op, 0, 0, 1]]);
    }
    for op in [0x02, 0x0b] {
        bad.extend([[op, 8, 0, 0], [op, 0x10, 0, 0], [op, 0xff, 0, 0]]);
    }
    for op in [0x08, 0x09, 0x0a] {
        bad.extend([[op, 8, 0, 0], [op, 0, 16, 0], [op, 0, 0, 1]]);
    }
    for op in [0x0c, 0x0d, 0x0e, 0x30, 0x31] {
        bad.extend([
            [op, 8, 0, 0],
            [op, 0x10, 0, 0],
            [op, 0, 1, 0],
            [op, 0, 0, 1],
        ]);
    }
    for op in [0x10, 0x11, 0x12, 0x13, 0x19, 0x1a] {
        bad.extend([[op, 0x08, 0, 0], [op, 0x40, 0, 0]]);
    }
    for op in [0x19, 0x1a] {
        bad.extend([[op, 0, 1, 0], [op, 0, 0, 1]]);
    }
    for op in [0x14, 0x15, 0x16, 0x29, 0x2a, 0x2b, 0x2c] {
        bad.extend([[op, 0x04, 0, 0], [op, 0x40, 0, 0]]);
    }
    for op in [0x16, 0x17, 0x18] {
        bad.extend([[op, 0, 1, 0], [op, 0, 0, 1]]);
    }
    for op in [0x17, 0x18] {
        bad.extend([[op, 0x04, 0, 0], [op, 0x80, 0, 0]]);
    }
    bad.extend([
        [0x1b, 4, 0, 0],
        [0x1b, 0x10, 0, 0],
        [0x1b, 0, 8, 0],
        [0x1b, 0, 0, 8],
    ]);
    for op in [0x32, 0x33, 0x34, 0x35] {
        bad.extend([
            [op, 4, 0, 0],
            [op, 0x10, 0, 0],
            [op, 0, 1, 0],
            [op, 0, 0, 1],
        ]);
    }
    bad.extend([[0x36, 0, 1, 0], [0x36, 0, 0, 1], [0x38, 1, 0, 0]]);
    for bytes in bad {
        assert!(
            isa::decode(bytes).is_err(),
            "invalid encoding accepted {bytes:02x?}"
        );
        let (mut vm, mut memory) = one(bytes);
        let old_r = vm.state.r;
        let old_p = vm.state.p;
        assert!(
            matches!(vm.run(&mut memory), Outcome::Fault(_)),
            "invalid VM encoding {bytes:02x?}"
        );
        assert_eq!(vm.state.r, old_r);
        assert_eq!(vm.state.p, old_p);
        assert_eq!(vm.state.pc, BASE);
        assert_eq!(vm.state.sp, STACK_LAST);
        assert_eq!(vm.state.retired, 0);
        assert_eq!(vm.state.fuel, 128);
    }
}

#[test]
fn integer_operations_have_explicit_fixed_width_results() {
    let cases = [
        ([0x01, 0x10, 0, 0], 0xaaaa, 0xbeef, 0xbeef),
        ([0x02, 0, 0x34, 0x12], 0, 0, 0x1234),
        ([0x03, 0x10, 0, 0], 0xffff, 1, 0),
        ([0x04, 0x10, 0, 0], 0, 1, 0xffff),
        ([0x05, 0x10, 0, 0], 0xf0f0, 0x0ff0, 0x00f0),
        ([0x06, 0x10, 0, 0], 0xf0f0, 0x0ff0, 0xfff0),
        ([0x07, 0x10, 0, 0], 0xf0f0, 0x0ff0, 0xff00),
        ([0x08, 0, 1, 0], 0x8001, 0, 2),
        ([0x09, 0, 1, 0], 0x8001, 0, 0x4000),
        ([0x0a, 0, 1, 0], 0x8001, 0, 0xc000),
        ([0x0b, 0, 5, 0], 0xfffe, 0, 3),
        ([0x0c, 0, 0, 0], 0xab80, 0, 0x0080),
        ([0x0d, 0, 0, 0], 0xab80, 0, 0xff80),
        ([0x0d, 0, 0, 0], 0xab7f, 0, 0x007f),
        ([0x0e, 0, 0, 0], 0xa5f0, 0, 0x5a0f),
        ([0x08, 0, 0, 0], 0x8123, 0, 0x8123),
        ([0x09, 0, 15, 0], 0x8000, 0, 1),
        ([0x0a, 0, 15, 0], 0x8000, 0, 0xffff),
        ([0x0a, 0, 15, 0], 0x7fff, 0, 0),
    ];
    for (bytes, left, right, expected) in cases {
        let (mut vm, mut memory) = one(bytes);
        vm.state.r[0] = left;
        vm.state.r[1] = right;
        step(&mut vm, &mut memory);
        assert_eq!(vm.state.r[0], expected, "{bytes:02x?}");
        assert_eq!(vm.state.r[1], right);
        assert_eq!(vm.state.pc, BASE + 4);
        assert_eq!(vm.state.retired, 1);
        assert_eq!(vm.state.fuel, 0);
    }
    let (mut vm, mut memory) = one([0, 0, 0, 0]);
    let old_r = vm.state.r;
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.r, old_r);
}

#[test]
fn pointer_construction_arithmetic_and_extraction_are_linear() {
    for index in 0..4 {
        let (mut vm, mut memory) = one([0x1c + index, 0x12, 0x34, 0x56]);
        step(&mut vm, &mut memory);
        assert_eq!(vm.state.p[index as usize], 0x56_3412);
    }
    let (mut vm, mut memory) = one([0x16, 0x13, 0, 0]);
    vm.state.p[1] = 0xab_cdef;
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.p[3], 0xab_cdef);
    for (op, start, amount, expected) in [
        (0x17, 0x04_fffe, 3, 0x05_0001),
        (0x18, 0x05_0001, 3, 0x04_fffe),
    ] {
        let (mut vm, mut memory) = one([op, 0x62, 0, 0]);
        vm.state.p[2] = start;
        vm.state.r[6] = amount;
        step(&mut vm, &mut memory);
        assert_eq!(vm.state.p[2], expected);
    }
    for (op, expected) in [(0x19, 0xcdef), (0x1a, 0x00ab)] {
        let (mut vm, mut memory) = one([op, 0x37, 0, 0]);
        vm.state.p[3] = 0xab_cdef;
        step(&mut vm, &mut memory);
        assert_eq!(vm.state.r[7], expected);
    }
    let (mut vm, mut memory) = one([0x1b, 2, 6, 7]);
    vm.state.r[6] = 0xcdef;
    vm.state.r[7] = 0x00ab;
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.p[2], 0xab_cdef);
}

#[test]
fn pointer_overflow_and_underflow_leave_registers_unchanged() {
    for (op, pointer, amount) in [(0x17, 0xff_ffff, 1), (0x17, 0xff_ff00, 0x100), (0x18, 0, 1)] {
        let (mut vm, mut memory) = one([op, 0x10, 0, 0]);
        vm.state.p[0] = pointer;
        vm.state.r[1] = amount;
        fault(&mut vm, &mut memory, FaultCause::AddressOverflow);
        assert_eq!(vm.state.p[0], pointer);
        assert_eq!(vm.state.pc, BASE);
        assert_eq!(vm.state.retired, 0);
        assert_eq!(vm.state.fuel, 128);
    }
    let (mut vm, mut memory) = one([0x1b, 2, 6, 7]);
    vm.state.r[6] = 0x1234;
    vm.state.r[7] = 256;
    let old = vm.state.p[2];
    fault(&mut vm, &mut memory, FaultCause::AddressOverflow);
    assert_eq!(vm.state.p[2], old);
}

#[test]
fn multibyte_loads_and_stores_cross_64k_and_cache_line_boundaries() {
    let cases = [
        (0x10, 1, 0x00ef),
        (0x11, 2, 0xbeef),
        (0x12, 1, 0xbeef),
        (0x13, 2, 0xbeef),
    ];
    for (op, length, expected) in cases {
        for address in [0x04_ffff, 0x04_017f, 0x04_0101] {
            let (mut vm, mut memory) = one([op, 0x27, 0, 0]);
            vm.state.p[2] = address;
            vm.state.r[7] = 0xbeef;
            memory
                .write(
                    address,
                    &if op <= 0x11 {
                        [0xef, 0xbe, 0xa5]
                    } else {
                        [0xa5, 0x5a, 0xcc]
                    },
                )
                .unwrap();
            step(&mut vm, &mut memory);
            if op <= 0x11 {
                assert_eq!(vm.state.r[7], expected);
            } else {
                assert_eq!(
                    memory.read(address, length).unwrap(),
                    &([0xef, 0xbe][..length as usize])
                );
                assert_eq!(
                    memory.read(address + length, 1).unwrap(),
                    &[if length == 1 { 0x5a } else { 0xcc }]
                );
            }
        }
    }
    for op in [0x14, 0x15] {
        let (mut vm, mut memory) = one([op, 0x13, 0, 0]);
        vm.state.p[1] = 0x04_fffe;
        vm.state.p[3] = 0xab_cdef;
        memory.write(0x04_fffe, &[0x12, 0x34, 0x56]).unwrap();
        step(&mut vm, &mut memory);
        if op == 0x14 {
            assert_eq!(vm.state.p[3], 0x56_3412);
        } else {
            assert_eq!(memory.read(0x04_fffe, 3).unwrap(), &[0xef, 0xcd, 0xab]);
        }
    }
    let (mut vm, mut memory) = one([0x11, 0, 0xff, 0xff]);
    vm.state.p[0] = BASE;
    memory.write(0x04_ffff, &[0x34, 0x12]).unwrap();
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.r[0], 0x1234);
}

#[test]
fn arena_and_24bit_end_bounds_are_checked_without_partial_writes() {
    for (op, address, expected) in [
        (0x10, BASE - 1, FaultCause::OutOfArena),
        (0x13, STACK_LAST, FaultCause::OutOfArena),
        (0x15, STACK_LAST - 1, FaultCause::OutOfArena),
        (0x10, STACK_LAST + 1, FaultCause::OutOfArena),
    ] {
        let (mut vm, mut memory) = one([op, 0, 0, 0]);
        vm.state.p[0] = address;
        vm.state.r[0] = 0x1234;
        memory.write(STACK_LAST - 1, &[0xaa, 0xbb]).unwrap();
        fault(&mut vm, &mut memory, expected);
        assert_eq!(memory.read(STACK_LAST - 1, 2).unwrap(), &[0xaa, 0xbb]);
        assert_eq!(vm.state.r[0], 0x1234);
        assert_eq!(vm.state.retired, 0);
    }
    let (mut vm, mut memory) = fixture_at(&[[0x10, 0, 0, 0], [0x20, 0, 0, 4]], BASE, 0xff_ffff);
    vm.state.p[0] = 0xff_ffff;
    memory.write(0xff_ffff, &[0xa5]).unwrap();
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.r[0], 0xa5);
    for op in [0x11, 0x13, 0x14, 0x15] {
        let (mut vm, mut memory) = fixture_at(&[[op, 0, 0, 0], [0x20, 0, 0, 4]], BASE, 0xff_ffff);
        vm.state.p[0] = 0xff_ffff;
        memory.write(0xff_ffff, &[0xa5]).unwrap();
        fault(&mut vm, &mut memory, FaultCause::AddressOverflow);
        assert_eq!(memory.read(0xff_ffff, 1).unwrap(), &[0xa5]);
    }
    let (mut vm, mut memory) = one([0x10, 0, 1, 0]);
    vm.state.p[0] = 0xff_ffff;
    fault(&mut vm, &mut memory, FaultCause::AddressOverflow);
}

#[test]
fn writes_into_code_are_rejected_but_reading_code_is_allowed() {
    for op in [0x12, 0x13, 0x15] {
        let (mut vm, mut memory) = one([op, 0, 0, 0]);
        vm.state.p[0] = BASE;
        let original = memory.read(BASE, 8).unwrap().to_vec();
        fault(&mut vm, &mut memory, FaultCause::ReadOnly);
        assert_eq!(memory.read(BASE, 8).unwrap(), original);
    }
    let (mut vm, mut memory) = one([0x13, 0, 0, 0]);
    vm.state.p[0] = BASE + 7;
    memory.write(BASE + 8, &[0xa5]).unwrap();
    fault(&mut vm, &mut memory, FaultCause::ReadOnly);
    assert_eq!(memory.read(BASE + 8, 1).unwrap(), &[0xa5]);
    let (mut vm, mut memory) = one([0x11, 0, 0, 0]);
    vm.state.p[0] = BASE;
    step(&mut vm, &mut memory);
    assert_eq!(vm.state.r[0], 0x0011);
}

#[test]
fn out_of_arena_pointers_remain_valid_values_until_dereferenced() {
    let (mut vm, mut memory) = fixture(&[
        [0x1c, 0, 0, 0],
        [0x16, 0x01, 0, 0],
        [0x15, 0x20, 0, 0],
        [0x14, 0x23, 0, 0],
        [0x10, 0x10, 0, 0],
        [0x20, 0, 0, 4],
    ]);
    vm.state.p[2] = BASE + 0x100;
    vm.refuel(4);
    assert!(matches!(vm.run(&mut memory), Outcome::FuelExhausted));
    assert_eq!(vm.state.p[0], 0);
    assert_eq!(vm.state.p[1], 0);
    assert_eq!(vm.state.p[3], 0);
    assert_eq!(memory.read(BASE + 0x100, 3).unwrap(), &[0, 0, 0]);
    vm.refuel(1);
    fault(&mut vm, &mut memory, FaultCause::OutOfArena);
    assert_eq!(vm.state.retired, 4);
}

#[test]
fn each_integer_and_pointer_branch_selects_the_expected_pc() {
    let integer_cases = [
        (0x23, 5, 5, true),
        (0x23, 5, 6, false),
        (0x24, 5, 6, true),
        (0x24, 5, 5, false),
        (0x25, 0xffff, 1, false),
        (0x25, 1, 0xffff, true),
        (0x26, 0xffff, 1, true),
        (0x26, 1, 0xffff, false),
        (0x26, 1, 1, true),
        (0x27, 0xffff, 1, true),
        (0x27, 1, 0xffff, false),
        (0x28, 0xffff, 1, false),
        (0x28, 1, 0xffff, true),
        (0x28, 0x8000, 0x8000, true),
    ];
    for (op, left, right, taken) in integer_cases {
        let (mut vm, mut memory) = fixture(&[[op, 0x10, 1, 0], [0, 0, 0, 0], [0x20, 0, 0, 4]]);
        vm.state.r[0] = left;
        vm.state.r[1] = right;
        step(&mut vm, &mut memory);
        assert_eq!(
            vm.state.pc,
            BASE + if taken { 8 } else { 4 },
            "branch {op:02x}, {left:04x}, {right:04x}"
        );
    }
    for (op, left, right, taken) in [
        (0x29, 0xff_ffff, 0xff_ffff, true),
        (0x29, 0, 1, false),
        (0x2a, 0, 1, true),
        (0x2a, 1, 1, false),
        (0x2b, 0, 0xff_ffff, true),
        (0x2b, 0xff_ffff, 0, false),
        (0x2c, 0xff_ffff, 0, true),
        (0x2c, 0, 0xff_ffff, false),
        (0x2c, 1, 1, true),
    ] {
        let (mut vm, mut memory) = fixture(&[[op, 0x10, 1, 0], [0, 0, 0, 0], [0x20, 0, 0, 4]]);
        vm.state.p[0] = left;
        vm.state.p[1] = right;
        step(&mut vm, &mut memory);
        assert_eq!(vm.state.pc, BASE + if taken { 8 } else { 4 });
    }
    let (mut vm, mut memory) = one([0x23, 0x10, 0xff, 0xff]);
    vm.state.r[0] = 7;
    vm.state.r[1] = 7;
    step(&mut vm, &mut memory);
    assert_eq!(
        vm.state.pc, BASE,
        "relative offsets are signed and measured in instructions"
    );
}

