    vm.refuel(3);
    assert!(matches!(vm.run(&mut memory), Outcome::FuelExhausted));
    assert_eq!(vm.state.sp, STACK_LAST - 5);
    assert_eq!(vm.state.p[2], STACK_LAST - 5);
    assert_eq!(
        memory.read(STACK_LAST - 4, 5).unwrap(),
        &[0xef, 0xcd, 0xab, 0xef, 0xbe]
    );
