#[test]
fn step_one_retires_one_opcode_and_reaches_the_same_fuel_boundary_as_run() {
    let words = [
        [0x02, 2, 0xef, 0xbe],
        [0x13, 2, 0, 0],
        [0x0b, 2, 1, 0],
        [0x20, 0, 0, 4],
    ];
    let (mut sliced, mut sliced_memory) = fixture(&words);
    let (mut continuous, mut continuous_memory) = fixture(&words);
    for vm in [&mut sliced, &mut continuous] {
        vm.state.p[0] = BASE + 0x17f;
        vm.refuel(3);
    }
    for memory in [&mut sliced_memory, &mut continuous_memory] {
        memory
            .write(BASE + 0x17e, &[0xa5, 0x11, 0x22, 0xcc])
            .unwrap();
    }
    assert!(sliced.step_one(&mut sliced_memory).is_none());
    assert_eq!(sliced.state.pc, BASE + 4);
    assert_eq!(sliced.state.r[2], 0xbeef);
    assert_eq!((sliced.state.fuel, sliced.state.retired), (2, 1));
    assert_eq!(
        sliced_memory.read(BASE + 0x17e, 4).unwrap(),
        [0xa5, 0x11, 0x22, 0xcc]
    );
    assert!(sliced.step_one(&mut sliced_memory).is_none());
    assert_eq!(
        sliced_memory.read(BASE + 0x17e, 4).unwrap(),
        [0xa5, 0xef, 0xbe, 0xcc]
    );
    assert!(sliced.step_one(&mut sliced_memory).is_none());
    assert_eq!(sliced.state.r[2], 0xbef0);
    assert_eq!(
        sliced.step_one(&mut sliced_memory),
        Some(Outcome::FuelExhausted)
    );
    assert_eq!(
        continuous.run(&mut continuous_memory),
        Outcome::FuelExhausted
    );
    assert_eq!(sliced.state, continuous.state);
    assert_eq!(
        sliced_memory.read(BASE + 0x17e, 4).unwrap(),
        continuous_memory.read(BASE + 0x17e, 4).unwrap()
    );
}

