fn step_one_and_run_preserve_a_split_store_until_all_lines_are_available() {
    let words = [[0x13, 2, 0, 0], [0x20, 0, 0, 4]];
    let (mut sliced, mut sliced_memory) = fixture(&words);
    let (mut continuous, mut continuous_memory) = fixture(&words);
    for vm in [&mut sliced, &mut continuous] {
        vm.state.p[0] = BASE + 0x17f;
        vm.state.r[2] = 0xbeef;
        vm.refuel(1);
    }
    for memory in [&mut sliced_memory, &mut continuous_memory] {
        memory
            .write(BASE + 0x17e, &[0xa5, 0x11, 0x22, 0xcc])
            .unwrap();
        memory.hold_line(BASE + 0x180);
    }
    let before = sliced.state.clone();
    let wait = Outcome::WaitMemory { line: BASE + 0x180 };
    for _ in 0..3 {
        assert_eq!(sliced.step_one(&mut sliced_memory), Some(wait.clone()));
        assert_eq!(continuous.run(&mut continuous_memory), wait);
        assert_eq!(sliced.state, before);
        assert_eq!(continuous.state, before);
        assert_eq!(
            sliced_memory.read(BASE + 0x17e, 4).unwrap(),
            [0xa5, 0x11, 0x22, 0xcc]
        );
    }
    sliced_memory.release_line(BASE + 0x180);
    continuous_memory.release_line(BASE + 0x180);
    assert!(sliced.step_one(&mut sliced_memory).is_none());
    assert_eq!(
        continuous.run(&mut continuous_memory),
        Outcome::FuelExhausted
    );
    assert_eq!(sliced.state, continuous.state);
    assert_eq!((sliced.state.fuel, sliced.state.retired), (0, 1));
    assert_eq!(
        sliced_memory.read(BASE + 0x17e, 4).unwrap(),
        [0xa5, 0xef, 0xbe, 0xcc]
    );
}

#[test]
fn step_one_matches_run_for_pending_syscall_priority_and_completion() {
    let words = [[0x36, 0x20, 0, 0], [0x0b, 2, 1, 0], [0x20, 0, 0, 4]];
    let (mut sliced, mut sliced_memory) = fixture(&words);
    let (mut continuous, mut continuous_memory) = fixture(&words);
    sliced.refuel(3);
    continuous.refuel(3);
    let accepted = sliced.step_one(&mut sliced_memory).unwrap();
    assert_eq!(continuous.run(&mut continuous_memory), accepted);
    let request = match &accepted {
        Outcome::Syscall(request) => request,
        other => panic!("expected syscall, received {other:?}"),
    };
    assert_eq!(
        (sliced.state.pc, sliced.state.fuel, sliced.state.retired),
        (BASE + 4, 2, 1)
    );
    sliced.refuel(0);
    continuous.refuel(0);
    let before = sliced.state.clone();
    for _ in 0..2 {
        assert_eq!(sliced.step_one(&mut sliced_memory), Some(accepted.clone()));
        assert_eq!(continuous.run(&mut continuous_memory), accepted);
        assert_eq!(sliced.state, before);
        assert_eq!(continuous.state, before);
    }
    for vm in [&mut sliced, &mut continuous] {
        assert!(
            vm.complete_syscall(request.token + 1, ReturnValues::status(99))
                .is_err()
        );
        assert_eq!(vm.state, before);
        let mut values = ReturnValues::status(23);
        values.r[7] = Some(0xabcd);
        values.p[2] = Some(0xffffff);
        vm.complete_syscall(request.token, values).unwrap();
        vm.refuel(1);
    }
    assert!(sliced.step_one(&mut sliced_memory).is_none());
    assert_eq!(
        continuous.run(&mut continuous_memory),
        Outcome::FuelExhausted
    );
    assert_eq!(sliced.state, continuous.state);
    assert_eq!(
        (sliced.state.r[0], sliced.state.r[2], sliced.state.r[7]),
        (23, 1, 0xabcd)
    );
    assert_eq!(sliced.state.p[2], 0xffffff);
    assert_eq!(sliced.state.retired, 2);
}

#[test]
fn step_one_and_run_keep_faults_and_exits_terminal_after_refueling() {
    for word in [[0xff, 0, 0, 0], [0x38, 0, 7, 0x10]] {
        let (mut sliced, mut sliced_memory) = fixture(&[word]);
        let (mut continuous, mut continuous_memory) = fixture(&[word]);
        let terminal = sliced.step_one(&mut sliced_memory).unwrap();
        assert!(matches!(terminal, Outcome::Fault(_)));
        assert_eq!(continuous.run(&mut continuous_memory), terminal);
        assert_eq!(sliced.state, continuous.state);
        assert_eq!(sliced.state.retired, u64::from(word[0] == 0x38));
        sliced_memory.write(BASE, &[0, 0, 0, 0]).unwrap();
        continuous_memory.write(BASE, &[0, 0, 0, 0]).unwrap();
        sliced.refuel(44);
        continuous.refuel(44);
        let before = sliced.state.clone();
        assert_eq!(sliced.step_one(&mut sliced_memory), Some(terminal.clone()));
        assert_eq!(continuous.run(&mut continuous_memory), terminal);
        assert_eq!(sliced.state, before);
        assert_eq!(continuous.state, before);
    }
    let (mut sliced, mut sliced_memory) = fixture(&[[0x36, 0, 0, 0]]);
    let (mut continuous, mut continuous_memory) = fixture(&[[0x36, 0, 0, 0]]);
    for vm in [&mut sliced, &mut continuous] {
        vm.state.r[0] = 0xbeef;
        vm.refuel(1);
    }
    let request = match sliced.step_one(&mut sliced_memory).unwrap() {
        Outcome::Syscall(request) => request,
        other => panic!("expected exit, received {other:?}"),
    };
    assert_eq!(
        continuous.run(&mut continuous_memory),
        Outcome::Syscall(request.clone())
    );
    for vm in [&mut sliced, &mut continuous] {
        vm.exit_syscall(request.token, request.r[0]).unwrap();
        vm.refuel(3);
    }
    let before = sliced.state.clone();
    assert_eq!(
        sliced.step_one(&mut sliced_memory),
        Some(Outcome::Stopped { code: 0xbeef })
    );
    assert_eq!(
        continuous.run(&mut continuous_memory),
        Outcome::Stopped { code: 0xbeef }
    );
    assert_eq!(sliced.state, before);
    assert_eq!(continuous.state, before);
    assert_eq!((sliced.state.pc, sliced.state.retired), (BASE, 1));
}
